//! Direct decode-only transport comparison: SENS wire vs Rust serde_json.
//!
//! The input records come from one deterministic semantic corpus generated by
//! benchmarks/agent-messages/run.py. File I/O and process start are outside the
//! timed loop. This benchmark does not measure whole-language execution.

use sens::wire_decode_program;
use std::{env, fs, process::ExitCode, time::Instant};

fn records(bytes: &[u8]) -> Result<Vec<&[u8]>, String> {
    let mut out = Vec::new();
    let mut at = 0usize;
    while at < bytes.len() {
        let end_len = at.checked_add(4).ok_or("record header overflow")?;
        let header = bytes.get(at..end_len).ok_or("truncated record header")?;
        let len = u32::from_le_bytes(header.try_into().map_err(|_| "invalid record header")?) as usize;
        at = end_len;
        let end = at.checked_add(len).ok_or("record length overflow")?;
        let record = bytes.get(at..end).ok_or("truncated record payload")?;
        out.push(record);
        at = end;
    }
    if out.is_empty() {
        return Err("empty corpus".into());
    }
    Ok(out)
}

fn decode_one(form: &str, bytes: &[u8]) -> Result<(), String> {
    match form {
        "wire" => {
            let expr = wire_decode_program(bytes).ok_or_else(|| "invalid SENS wire".to_string())?;
            std::hint::black_box(expr);
        }
        "json" => {
            let value: serde_json::Value =
                serde_json::from_slice(bytes).map_err(|e| format!("invalid JSON: {e}"))?;
            std::hint::black_box(value);
        }
        _ => return Err(format!("unknown form {form}; expected wire|json")),
    }
    Ok(())
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 || args.len() > 4 {
        eprintln!("usage: transport_decode_bench wire|json RECORDS [rounds]");
        return ExitCode::from(2);
    }
    let form = &args[1];
    let bytes = match fs::read(&args[2]) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("cannot read corpus: {e}");
            return ExitCode::FAILURE;
        }
    };
    let records = match records(&bytes) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::FAILURE;
        }
    };
    let rounds: usize = match args.get(3).map(|s| s.parse::<usize>()).transpose() {
        Ok(Some(n)) if n > 0 => n,
        Ok(None) => 1,
        _ => {
            eprintln!("rounds must be a positive integer");
            return ExitCode::from(2);
        }
    };

    // Warm-up once before the measured section.
    for record in &records {
        if let Err(e) = decode_one(form, record) {
            eprintln!("{e}");
            return ExitCode::FAILURE;
        }
    }

    let start = Instant::now();
    for _ in 0..rounds {
        for record in &records {
            if let Err(e) = decode_one(form, record) {
                eprintln!("{e}");
                return ExitCode::FAILURE;
            }
        }
    }
    let elapsed = start.elapsed();
    let messages = records.len() * rounds;
    let ns_per_message = elapsed.as_secs_f64() * 1e9 / messages as f64;
    let msg_per_sec = messages as f64 / elapsed.as_secs_f64();

    println!(
        "form={form} messages={messages} elapsed_ns={:.0} ns_per_message={:.3} msg_per_sec={:.3}",
        elapsed.as_secs_f64() * 1e9,
        ns_per_message,
        msg_per_sec
    );
    ExitCode::SUCCESS
}
